import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  compareJSON, fetchEncryptStream, qryStore } from "../../../stores/Utils";

import {  TextInput_Cmpt, CheckBox_Cmpt, DropDwnPicker_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal } from "../../../components/DialogHRM";


const TextInput = TextInput_Cmpt();

const CheckBox = CheckBox_Cmpt();


const DropDwnPicker = DropDwnPicker_Cmpt();


const frmNm = "upd_fromMobile"

const UpdFeedfromMobile  = ({data, confirm}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};


	let flds = ["type","title", "description", "amount", "categoryId", "comprobanteId" ]

	const save  = async ()  => {
		let ffm = getStore(frmNm);
		let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )
		/* 

		*/ 
	
		let bdyq2 = {...getStore(qryStore())?.upd__incms_expns};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			"movementId": ffm["movementId"],
			year:getStore("date_current_year"),
		}
		bdyq2.data2update=diff.data;
		//console.log(bdyq2)
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			updStore(frmNm + "_bck", {});
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
		
	};

	
	let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )


	
	const handleOnSel = (v) =>{
	
	}
	

	return (
		<div
		style={{
			maxHeight: "80vh",
			width: "560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 25px"
		}}
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Actualizar Movimiento
				</p>
				<div className="flexSpace"/>
				
			</div>

			<TextInput  
				init={getStore(frmNm)?.["title"]} 
				label={"Nombre"} 
				width={520} 
				updChanges={(e)=>updFrm("title",e)}
			/>

				<div className="_dsplFlx " >
					
					<div className="" style={{maxWidth: 130 , marginLeft: 7}}>
						<TextInput  
							init={getStore(frmNm)?.["amount"]} 
							label={"Importe"} 
							width={120} 
							type={"number"}
							updChanges={(e)=>updFrm("amount",e)}
						/>
					</div>
					<div className="flexSpace"/>
					<div style={{marginTop:9}}>
						<DropDwnPicker 
							init={getStore(frmNm)?.["categoryId"]}
							lbl_empty={"Categorias"} 
							list={getStore("categories_pick_data")} 
							onSelect={(e)=>updFrm("categoryId",e)}
							direction={"right"}
						/>
					</div>
				</div>
		
				<TextInput  
					init={getStore(frmNm)?.["description"]} 
					label={"Descripcion"} 
					width={520} 
					updChanges={(e)=>updFrm("description",e)}
				/>

				<TextInput  
					init={getStore(frmNm)?.["comprobanteId"]} 
					label={"comprobanteId"} 
					width={520} 
					updChanges={(e)=>updFrm("comprobanteId",e)}
				/>
					
				
				<div className="_dsplFlx " style={{padding: "18px"}}>
					<div className="flexSpace"/>
					<CheckBox data={[
							{label: "Incomes", id:"income"},
							{label: "Expenses", id:"expense"}
						]}
						active={getStore(frmNm)?.["movementType"]}
						updSelect={(e)=>updFrm("movementType",e)}
					/>
					<div className="flexSpace"/>
				</div>

				
				<div style={{paddingTop: "38px"}}/>

				<div className="_dsplFlx ">
					<div className="flexSpace"/>
					{diff?.hasChange ?
					<div className="card">
						<button onClick={save}>
							Actualizar
						</button>
					</div>
					:null}
				</div>
			

			
		</div>
	);
};

export default UpdFeedfromMobile;
